// Parse Incoming: extract one WhatsApp message from the Meta webhook payload,
// drop status callbacks / own messages / duplicates.
const cfg = $('Config').first().json;
const body = $input.first().json.body || {};
const entries = Array.isArray(body.entry) ? body.entry : [];
let value = null, msg = null;
for (const e of entries) {
  for (const c of (e.changes || [])) {
    const v = c && c.value;
    if (v && Array.isArray(v.messages) && v.messages.length) { value = v; msg = v.messages[0]; break; }
  }
  if (msg) break;
}
if (!msg) return [];            // delivery / read status callbacks, etc.

const metadata = value.metadata || {};
if (cfg.phoneNumberId && metadata.phone_number_id &&
    String(metadata.phone_number_id) !== String(cfg.phoneNumberId)) return [];   // event for another number

const from = String(msg.from || '').replace(/\D/g, '');
const ownDigits = String(metadata.display_phone_number || '').replace(/\D/g, '');
if (!from || (ownDigits && from === ownDigits)) return [];                       // ignore our own number

// Duplicate-delivery protection (Meta retries webhooks)
const sd = $getWorkflowStaticData('global');
if (!sd.processed) sd.processed = {};
const nowMs = Date.now();
for (const k of Object.keys(sd.processed)) {
  if (nowMs - sd.processed[k] > 48 * 3600 * 1000) delete sd.processed[k];
}
if (msg.id && sd.processed[msg.id]) return [];
if (msg.id) sd.processed[msg.id] = nowMs;

let text = '';
const t = msg.type;
if (t === 'text') text = (msg.text && msg.text.body) || '';
else if (t === 'interactive') {
  const i = msg.interactive || {};
  text = (i.button_reply && i.button_reply.title) || (i.list_reply && i.list_reply.title) || '';
} else if (t === 'button') text = (msg.button && (msg.button.text || msg.button.payload)) || '';
text = String(text).replace(/\s+/g, ' ').trim().slice(0, 1000);

const contact = (value.contacts || [])[0] || {};
return [{ json: {
  from,
  name: (contact.profile && contact.profile.name) || '',
  messageId: msg.id || '',
  type: t,
  text,
  unsupported: !text,
  timestamp: msg.timestamp || ''
} }];

// Analyze Message: load state/customer/properties, run deterministic parsing,
// decide whether the LLM is needed and build the Ollama extraction request.
const cfg = $('Config').first().json;
const msg = $('Parse Incoming').first().json;

const norm = v => String(v === undefined || v === null ? '' : v).trim();
const digits = v => norm(v).replace(/\D/g, '');
const rows = name => $(name).all().map(i => i.json || {});
const numOrNull = v => { if (v === undefined || v === null || norm(v) === '') return null; const n = Number(norm(v).replace(/[^0-9.\-]/g, '')); return isFinite(n) ? n : null; };
const pad = n => String(n).padStart(2, '0');
const DAYN = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const MON3 = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];

// ---------- "now" in the business timezone ----------
function nowInTz(tz) {
  try {
    const parts = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date());
    const g = t => (parts.find(p => p.type === t) || {}).value;
    return { date: `${g('year')}-${g('month')}-${g('day')}`, time: `${g('hour')}:${g('minute')}` };
  } catch (e) {
    const d = new Date().toISOString();
    return { date: d.slice(0, 10), time: d.slice(11, 16) };
  }
}
const now = nowInTz(cfg.timezone || 'UTC');

const validYmd = (y, m, d) => { const dt = new Date(Date.UTC(y, m - 1, d)); return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d; };
const toYmd = (y, m, d) => `${y}-${pad(m)}-${pad(d)}`;
const addDays = (ymd, n) => { const [y, m, d] = ymd.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10); };
const weekdayOf = ymd => { const [y, m, d] = ymd.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d)).getUTCDay(); };

function normDate(v) {
  const s = norm(v); if (!s) return '';
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  if (/^\d{5}(\.\d+)?$/.test(s)) return new Date(Date.UTC(1899, 11, 30) + Math.floor(Number(s)) * 86400000).toISOString().slice(0, 10);
  return s;
}
function normTime(v) {
  const s = norm(v); if (!s) return '';
  if (/^\d{1,2}:\d{2}/.test(s)) { const p = s.split(':'); return pad(+p[0]) + ':' + p[1].slice(0, 2); }
  if (!isNaN(Number(s)) && Number(s) >= 0 && Number(s) < 1) { const mins = Math.round(Number(s) * 1440); return pad(Math.floor(mins / 60)) + ':' + pad(mins % 60); }
  return s;
}

// ---------- state / customer / properties ----------
const sr = rows('Read Conversation State').find(r => digits(r.CustomerPhone) && digits(r.CustomerPhone) === msg.from) || {};
let lastCriteria = null;
try { lastCriteria = sr.LastCriteria ? JSON.parse(sr.LastCriteria) : null; } catch (e) { lastCriteria = null; }
const BOOKING = ['ask_name', 'ask_email', 'ask_date', 'ask_time'];
let state = {
  stage: norm(sr.Stage) || 'idle',
  selectedPropertyId: norm(sr.SelectedPropertyID),
  name: norm(sr.CollectedName), email: norm(sr.CollectedEmail),
  date: normDate(sr.PreferredDate), time: normTime(sr.PreferredTime),
  lastResultIds: norm(sr.LastResultIDs).split(',').map(s => s.trim()).filter(Boolean),
  lastCriteria
};
if (norm(sr.LastMessageID) && msg.messageId && norm(sr.LastMessageID) === msg.messageId) return [];  // already handled

// session timeout for half-finished bookings
let sessionExpired = false;
const timeoutMin = Number(cfg.sessionTimeoutMinutes || 720);
const upd = Date.parse(norm(sr.UpdatedAt));
if (BOOKING.includes(state.stage) && isFinite(upd) && (Date.now() - upd) / 60000 > timeoutMin) {
  sessionExpired = true;
  state = Object.assign({}, state, { stage: 'idle', selectedPropertyId: '', name: '', email: '', date: '', time: '' });
}

const cr = rows('Read Customers').find(r => digits(r.CustomerPhone) && digits(r.CustomerPhone) === msg.from) || {};
const customer = { name: norm(cr.CustomerName), email: norm(cr.Email), budget: norm(cr.Budget), location: norm(cr.PreferredLocation), type: norm(cr.PreferredPropertyType), lastPropertyId: norm(cr.LastPropertyID) };

function sizeSqm(s) {
  const m = norm(s).toLowerCase().replace(/,/g, '').match(/(\d+(?:\.\d+)?)\s*(sqm|sq\.?\s?m|m2|m²|square\s*met(?:er|re)s?|acres?|hectares?|ha|sqft|sq\.?\s?ft|square\s*feet)?/);
  if (!m) return null;
  let n = parseFloat(m[1]); const u = m[2] || 'sqm';
  if (/acre/.test(u)) n *= 4046.86; else if (/hect|^ha$/.test(u)) n *= 10000; else if (/ft|feet/.test(u)) n *= 0.092903;
  return Math.round(n);
}
const props = rows('Read Properties').filter(p => norm(p.PropertyID)).map(p => ({
  id: norm(p.PropertyID), title: norm(p.Title), location: norm(p.Location), area: norm(p.Area),
  price: numOrNull(p.Price), currency: norm(p.Currency).toUpperCase(), size: norm(p.Size), sizeSqm: sizeSqm(p.Size),
  type: norm(p.PropertyType), description: norm(p.Description), features: norm(p.Features), status: norm(p.Status),
  image: norm(p.ImageURL), agent: norm(p.AgentName), agentPhone: norm(p.AgentPhone)
}));
const avail = props.filter(p => /^available$/i.test(p.status));
const uniq = arr => Array.from(new Set(arr.filter(Boolean)));
const knownLocs = uniq(props.flatMap(p => [p.location, p.area]));
const availLocs = uniq(avail.map(p => p.location));
const availTypes = uniq(avail.map(p => p.type));

// ---------- deterministic text parsing ----------
const text = msg.text;
const lower = text.toLowerCase();
const emailRe = /[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/;

const canonId = id => norm(id).toLowerCase().replace(/[^a-z0-9]/g, '').replace(/^([a-z]+)0+(?=\d)/, '$1');
const idMap = {}; props.forEach(p => { idMap[canonId(p.id)] = p; });
function findPropertyId(t) {
  const re = /\b([a-z]{1,4})[\s\-#]?0*(\d{1,6})\b/gi; let m;
  while ((m = re.exec(t))) { const key = (m[1] + m[2]).toLowerCase(); if (idMap[key]) return idMap[key].id; }
  return null;
}
function optionIndex(t, max) {
  const s = t.toLowerCase().trim(); let m;
  if ((m = s.match(/^(?:#|no\.?\s*|number\s*|option\s*|choice\s*|plot\s*|property\s*|the\s+)?(\d)\s*(?:st|nd|rd|th)?[.!)]?$/)) && +m[1] >= 1 && +m[1] <= max) return +m[1] - 1;
  if (s.length > 40) return null;
  if ((m = s.match(/\b(?:option|number|no\.?|#|choice|plot|property)\s*(\d)\b/)) && +m[1] >= 1 && +m[1] <= max) return +m[1] - 1;
  if ((m = s.match(/\b(first|second|third|fourth|fifth)\b/))) { const i = ['first','second','third','fourth','fifth'].indexOf(m[1]); if (i < max) return i; }
  return null;
}
function cleanName(t) {
  let s = t.replace(emailRe, ' ').replace(/\s+/g, ' ').trim();
  s = s.replace(/^(?:hi|hello|hey)[,!\s]+/i, '');
  s = s.replace(/^(?:my name is|my name's|name is|name:|this is|i am|i'm|im|it's|its|call me|you can call me|the name is|book (?:it )?(?:under|for))\s+/i, '');
  s = s.replace(/[.!,;:]+$/, '').trim();
  if (!/^[\p{L}][\p{L}\s.'’\-]{1,59}$/u.test(s)) return '';
  if (s.split(/\s+/).length > 5) return '';
  if (/^(yes|no|ok|okay|sure|thanks|thank you|hi|hello|hey|cancel|menu|stop|back|help)$/i.test(s)) return '';
  if (s === s.toLowerCase() || s === s.toUpperCase()) s = s.toLowerCase().replace(/(^|[\s'’\-])(\p{L})/gu, (m, a, b) => a + b.toUpperCase());
  return s;
}

function parseDate(t) {
  const s = t.toLowerCase(); const ty = +now.date.slice(0, 4); let m;
  const dmy = String(cfg.dateOrder || 'DMY').toUpperCase() !== 'MDY';
  if ((m = s.match(/\b(20\d{2})-(\d{1,2})-(\d{1,2})\b/))) { if (validYmd(+m[1], +m[2], +m[3])) return toYmd(+m[1], +m[2], +m[3]); }
  if ((m = s.match(/\b(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4}|\d{2})\b/))) {
    let y = +m[3]; if (y < 100) y += 2000;
    let d = dmy ? +m[1] : +m[2], mo = dmy ? +m[2] : +m[1];
    if (!validYmd(y, mo, d)) { const x = d; d = mo; mo = x; }
    if (validYmd(y, mo, d)) return toYmd(y, mo, d);
  }
  if ((m = s.match(/\b(\d{1,2})\/(\d{1,2})(?![\d\/])/))) {
    let d = dmy ? +m[1] : +m[2], mo = dmy ? +m[2] : +m[1], y = ty;
    if (!validYmd(y, mo, d)) { const x = d; d = mo; mo = x; }
    if (validYmd(y, mo, d)) { if (toYmd(y, mo, d) < now.date) y += 1; if (validYmd(y, mo, d)) return toYmd(y, mo, d); }
  }
  const MONRE = '(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)';
  const fromMD = (d, mon, yr) => {
    const mo = MON3.indexOf(mon.slice(0, 3)) + 1; let y = yr ? +yr : ty;
    if (!validYmd(y, mo, d)) return null;
    if (!yr && toYmd(y, mo, d) < now.date) y += 1;
    return validYmd(y, mo, d) ? toYmd(y, mo, d) : null;
  };
  let r;
  if ((m = s.match(new RegExp('\\b(\\d{1,2})(?:st|nd|rd|th)?\\s*(?:of\\s+)?' + MONRE + '\\b(?:,?\\s*(20\\d{2}))?', 'i'))) && (r = fromMD(+m[1], m[2], m[3]))) return r;
  if ((m = s.match(new RegExp('\\b' + MONRE + '\\.?\\s*(\\d{1,2})(?:st|nd|rd|th)?\\b(?:,?\\s*(20\\d{2}))?', 'i'))) && (r = fromMD(+m[2], m[1], m[3]))) return r;
  if (/\bday after tomorrow\b/.test(s)) return addDays(now.date, 2);
  if (/\btomorrow\b/.test(s)) return addDays(now.date, 1);
  if (/\b(today|tonight)\b/.test(s)) return now.date;
  if ((m = s.match(/\b(?:next|this|coming|on)?\s*(sun(?:day)?|mon(?:day)?|tue(?:s|sday)?|wed(?:s|nesday)?|thu(?:r|rs|rsday)?|fri(?:day)?|sat(?:urday)?)\b/))) {
    const idx = ['sun','mon','tue','wed','thu','fri','sat'].indexOf(m[1].slice(0, 3));
    let diff = (idx - weekdayOf(now.date) + 7) % 7; if (diff === 0) diff = 7;
    return addDays(now.date, diff);
  }
  return null;
}
function parseTime(t) {
  const s = t.toLowerCase(); let m;
  if ((m = s.match(/\b(\d{1,2})(?::(\d{2}))?\s*([ap])\.?\s?m\b\.?/))) {
    let h = +m[1]; const mi = m[2] ? +m[2] : 0;
    if (h >= 1 && h <= 12 && mi < 60) { if (m[3] === 'p' && h < 12) h += 12; if (m[3] === 'a' && h === 12) h = 0; return `${pad(h)}:${pad(mi)}`; }
  }
  if ((m = s.match(/\b([01]?\d|2[0-3]):([0-5]\d)\b/))) return `${pad(+m[1])}:${m[2]}`;
  if (/\b(noon|midday)\b/.test(s)) return '12:00';
  return null;
}
function parseMoney(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') return isFinite(v) && v > 0 ? v : null;
  const s = String(v).toLowerCase().replace(/,/g, '').replace(/\s+/g, '');
  const m = s.match(/(\d+(?:\.\d+)?)(k|m|mn|million|thousand|b|billion)?/); if (!m) return null;
  let n = parseFloat(m[1]); const u = m[2];
  if (u === 'k' || u === 'thousand') n *= 1e3; else if (u === 'm' || u === 'mn' || u === 'million') n *= 1e6; else if (u === 'b' || u === 'billion') n *= 1e9;
  return n > 0 ? n : null;
}
function budgetFromText(t) {
  const re = /([$₦€£])?\s*(\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?)(?!\d)\s*(k|m|mn|million|thousand|billion|b)?(?![a-z0-9])(?!\s*(?:sqm|sq|m2|square|acre|hectare|bed))/gi; let m;
  while ((m = re.exec(t))) {
    const prev = t[m.index - 1]; if (prev && /[a-z]/i.test(prev)) continue;
    const v = parseMoney(m[2] + (m[3] || ''));
    if (v && (m[1] || m[3] || v >= 1000)) return v;
  }
  return null;
}
function detectCurrency(t) {
  const s = t.toLowerCase();
  if (/₦|\bngn\b|naira/.test(s)) return 'NGN';
  if (/\$|\busd\b|dollars?/.test(s)) return 'USD';
  if (/€|\beur\b|euros?/.test(s)) return 'EUR';
  if (/£|\bgbp\b|pounds?/.test(s)) return 'GBP';
  return null;
}
const escRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
function findKnownLocation(t) {
  const s = t.toLowerCase(); let best = null;
  for (const loc of knownLocs) {
    if (new RegExp('(^|[^a-z0-9])' + escRe(loc.toLowerCase()) + '($|[^a-z0-9])').test(s) && (!best || loc.length > best.length)) best = loc;
  }
  return best;
}
function findType(t) {
  const m = t.toLowerCase().match(/\b(residential|commercial|farm|agricultural|industrial)?\s*(plot|plots|land|house|houses|apartment|apartments|flat|flats|villa|villas)\b/);
  return m ? ((m[1] ? m[1] + ' ' : '') + m[2].replace(/s$/, '')).trim() : null;
}
function findMinSize(t) {
  if (!/(at least|minimum|min\b|bigger than|larger than|more than|over|above|not less than)/i.test(t)) return null;
  const m = t.toLowerCase().replace(/,/g, '').match(/(\d+(?:\.\d+)?)\s*(sqm|sq\.?\s?m|m2|acres?|hectares?)\b/);
  return m ? sizeSqm(m[1] + ' ' + m[2]) : null;
}

const cmdText = lower.replace(/[^a-z ]/g, '').trim();
let cmd = null;
if (/^(reset|restart|start over|menu|new search|main menu)$/.test(cmdText)) cmd = 'reset';
else if (/^(cancel|cancel booking|stop|exit|quit)$/.test(cmdText)) cmd = 'cancel';
else if (/^change (my )?(details|name|email)$/.test(cmdText)) cmd = 'change_details';
const isGreeting = /^(hi|hello|hey|hola|howdy|good\s*(morning|afternoon|evening)|start|help)[\s!.,?]*$/i.test(text);

const propertyId = findPropertyId(text);
const optIdx = state.stage === 'results_shown' ? optionIndex(text, Math.max(1, state.lastResultIds.length)) : null;
const parsed = {
  email: (text.match(emailRe) || [null])[0] ? text.match(emailRe)[0].toLowerCase() : null,
  nameCandidate: cleanName(text),
  date: parseDate(text), time: parseTime(text),
  propertyId, optionIndex: optIdx,
  location: findKnownLocation(text), type: findType(text),
  budget: budgetFromText(text), currency: detectCurrency(text), minSize: findMinSize(text)
};

const bookingStage = BOOKING.includes(state.stage);
const needsLLM = !msg.unsupported && !bookingStage && !cmd && !isGreeting && !propertyId && !(optIdx !== null && state.lastResultIds[optIdx]);

// ---------- Ollama extraction request ----------
const system = [
  'You are the language-understanding module of a real-estate WhatsApp assistant. You do not chat. You output exactly one JSON object and nothing else.',
  `Today is ${now.date} (${DAYN[weekdayOf(now.date)]}). Timezone: ${cfg.timezone || 'UTC'}.`,
  'Return exactly these keys:',
  '{"intent":"search_property|book_visit|property_question|greeting|general_question|other","location":null,"property_type":null,"max_budget":null,"min_budget":null,"currency":null,"min_size_sqm":null,"property_id":null,"visit_date":null,"visit_time":null}',
  'Rules:',
  '- intent: search_property = wants to find or buy plots/properties; book_visit = wants to visit, view or book an appointment; property_question = asks about one specific listing; greeting = only says hello; general_question = other questions about the company or the process; other = anything else.',
  '- location: the place the customer asks for, copied from THEIR message (city, area or neighbourhood). null if the message names no place.',
  '- property_type: a short phrase such as "plot", "residential plot", "house". null if not stated.',
  '- max_budget and min_budget: plain numbers. 50k = 50000, 2m or 2 million = 2000000. "under", "up to", "below", "within" mean max_budget. null if no budget is stated.',
  '- currency: ISO code ONLY if the customer explicitly writes a currency or symbol, otherwise null.',
  '- min_size_sqm: number of square metres only if the customer states a minimum size, else null.',
  '- property_id: only if the message contains an ID like P001, else null.',
  '- visit_date (YYYY-MM-DD) and visit_time (HH:MM, 24h): only if the customer gives them. Resolve words like tomorrow or next Friday using today\'s date.',
  'Never copy values from these instructions or examples unless the customer wrote them.',
  `Locations in our database: ${availLocs.join(', ') || 'none'}.`,
  `Property types in our database: ${availTypes.join(', ') || 'none'}.`,
  'Example input: I need a plot in Springfield. My budget is $50,000.',
  'Example output: {"intent":"search_property","location":"Springfield","property_type":"plot","max_budget":50000,"min_budget":null,"currency":"USD","min_size_sqm":null,"property_id":null,"visit_date":null,"visit_time":null}',
  'Example input: hello, what do you do?',
  'Example output: {"intent":"general_question","location":null,"property_type":null,"max_budget":null,"min_budget":null,"currency":null,"min_size_sqm":null,"property_id":null,"visit_date":null,"visit_time":null}'
].join('\n');
const userMsg = (state.lastResultIds.length ? `The customer was previously shown property IDs: ${state.lastResultIds.join(', ')}.\n` : '') + `Customer message: ${text}`;
const ollamaRequest = {
  model: cfg.ollamaModel || 'qwen2.5:3b', stream: false, format: 'json', keep_alive: '30m',
  options: { temperature: 0, num_ctx: 4096, num_predict: 300 },
  messages: [{ role: 'system', content: system }, { role: 'user', content: userMsg }]
};

return [{ json: {
  phone: msg.from, profileName: msg.name, messageId: msg.messageId, text, unsupported: !!msg.unsupported,
  now, state, customer, props, parsed,
  flags: { isGreeting, cmd, bookingStage, sessionExpired },
  needsLLM, ollamaRequest
} }];

// Resolve Action: the conversation state machine. Deterministic; Ollama only
// supplies extracted fields (and later, friendly wording).
const ctx = $('Analyze Message').first().json;
const cfg = $('Config').first().json;
const props = ctx.props || [];
const P = ctx.parsed;
const flags = ctx.flags;
const now = ctx.now;
const phone = ctx.phone;
const text = ctx.text;
const biz = cfg.businessName || 'our team';
const nowIso = new Date().toISOString();

const norm = v => String(v === undefined || v === null ? '' : v).trim();
const pad = n => String(n).padStart(2, '0');
const DAYN = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const MONN = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const BOOKING = ['ask_name', 'ask_email', 'ask_date', 'ask_time'];
const isBooking = s => BOOKING.includes(s);
const isAvail = p => !!p && /^available$/i.test(p.status);
const canonId = id => norm(id).toLowerCase().replace(/[^a-z0-9]/g, '').replace(/^([a-z]+)0+(?=\d)/, '$1');
const byId = id => props.find(p => canonId(p.id) === canonId(id));
const uniq = arr => Array.from(new Set(arr.filter(Boolean)));
const avail = props.filter(isAvail);
const availLocs = uniq(avail.map(p => p.location));
const availTypes = uniq(avail.map(p => p.type));

// ---------- formatting ----------
const weekdayOf = ymd => { const [y, m, d] = ymd.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d)).getUTCDay(); };
const addDays = (ymd, n) => { const [y, m, d] = ymd.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10); };
const prettyDate = ymd => { const [y, m, d] = ymd.split('-').map(Number); return `${DAYN[weekdayOf(ymd)]}, ${d} ${MONN[m - 1]} ${y}`; };
const prettyTime = hm => { let [h, mi] = hm.split(':').map(Number); const ap = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12; return `${h}:${pad(mi)} ${ap}`; };
const SYM = { USD: '$', NGN: '₦', EUR: '€', GBP: '£' };
const fmtPrice = (n, c) => { const num = Number(n); if (n === null || !isFinite(num)) return 'Price on request'; const s = num.toLocaleString('en-US', { maximumFractionDigits: 0 }); const cur = (c || '').toUpperCase(); return SYM[cur] ? SYM[cur] + s : (cur ? cur + ' ' + s : s); };
