// ---------- scheduling rules ----------
const allowedDays = String(cfg.visitDays === undefined || cfg.visitDays === '' ? '1,2,3,4,5,6' : cfg.visitDays).split(',').map(s => s.trim()).filter(Boolean).map(Number);
const earliest = String(cfg.visitEarliest || '09:00'), latest = String(cfg.visitLatest || '18:00');
const maxAdv = Number(cfg.maxAdvanceDays || 90);
