  if (diffDays(now.date, date) > maxAdv) return `Please choose a date within the next ${maxAdv} days.`;
  const wd = weekdayOf(date);
  if (!allowedDays.includes(wd)) return `We don't schedule viewings on ${DAYN[wd]}s. Viewings are available ${dayList()}.`;
  return null;
}
function checkTime(date, time) {
