function exampleDate() {
  for (let i = 1; i < 15; i++) { const d = addDays(now.date, i); if (allowedDays.includes(weekdayOf(d))) { const [, m, dd] = d.split('-').map(Number); return `${DAYN[weekdayOf(d)]} ${dd} ${MONN[m - 1]}`; } }
  return 'tomorrow';
