// ---------- LLM output ----------
function readLLM() {
  if (!ctx.needsLLM) return null;
  const j = $input.first().json || {};
  const raw = j.message && j.message.content; if (!raw) return null;
  try { const o = JSON.parse(raw); return (o && typeof o === 'object') ? o : null; }
  catch (e) { const m = String(raw).match(/\{[\s\S]*\}/); if (m) { try { return JSON.parse(m[0]); } catch (e2) { return null; } } return null; }
}
const llm = readLLM();
const L = llm || {};
const BOOK_RE = /\b(visit|view|viewing|book|booking|appointment|schedule|inspect|inspection|tour|see (?:it|the|this|that))\b/i;
const DETAILS_RE = /\b(details?|more info|tell me more|tell me about|information|info|about|how much|price of)\b/i;
const wantsBooking = BOOK_RE.test(text) || L.intent === 'book_visit';
const wantsDetails = (DETAILS_RE.test(text) || L.intent === 'property_question') && !BOOK_RE.test(text);

function parseMoney(v) {
