const cleanVal = v => { const s = norm(v); return (!s || /^(null|none|n\/a|unknown|any|anywhere|undefined)$/i.test(s)) ? null : s; };
const words = text.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
