  return all.find(k => k.toLowerCase() === l) || all.find(k => { const kl = k.toLowerCase(); return kl.includes(l) || l.includes(kl); }) || loc;
}

// ---------- state & output ----------
const fresh = () => ({ stage: 'idle', selectedPropertyId: '', name: '', email: '', date: '', time: '', lastResultIds: [], lastCriteria: null });
let st = Object.assign({}, ctx.state);
let crit = null;
let prefix = flags.sessionExpired ? '⏳ Your earlier booking session timed out, so I started fresh.\n\n' : '';
const out = { action: 'reply', messages: [], compose: null, booking: null, ollamaRequest: null };
const say = t => { out.messages.push({ type: 'text', body: (prefix + t).slice(0, 4000) }); prefix = ''; };

function greeting() {
  const p0 = avail[0];
  const ex = p0 ? `${p0.location}, budget ${fmtPrice(Math.ceil((p0.price || 50000) * 1.1 / 1000) * 1000, p0.currency)}` : 'my preferred area, budget 50,000';
  return `👋 Hello! Welcome to *${biz}*.\n\nI can help you find available plots and properties and book an in-person viewing.\n\nJust tell me the *location* and your *budget*, for example:\n_"I need a plot in ${ex}"_\n\nType *MENU* at any time to start over.`;
}

// ---------- search ----------
function typeNorm(s) { return norm(s).toLowerCase().replace(/\b(land|lot|parcel)s?\b/g, 'plot').replace(/\b(home|homes)\b/g, 'house').replace(/\b(flat|condo)s?\b/g, 'apartment').replace(/\b(plot|house|apartment|villa)s\b/g, '$1'); }
function typeTokens(s) { return typeNorm(s).split(/\s+/).filter(t => t && !['a','an','the','for','sale','property','properties','in','of'].includes(t)); }
function runSearch(c) {
  let list = avail.slice();
  const afterStatus = list.length;
  let locMatched = list;
  if (c.location) {
    const l = c.location.toLowerCase();
    locMatched = list.filter(p => [p.location, p.area, p.title].some(f => { const x = f.toLowerCase(); return x && (x.includes(l) || l.includes(x)); }));
    list = locMatched;
  }
  if (c.type) { const tk = typeTokens(c.type); if (tk.length) list = list.filter(p => { const pt = typeNorm(p.type); return tk.every(t => pt.includes(t)); }); }
  const afterType = list;
  if (c.currency) list = list.filter(p => !p.currency || p.currency === c.currency);
  if (c.minSize) list = list.filter(p => p.sizeSqm === null || p.sizeSqm >= c.minSize);
  const typeAndLocOk = list;
  if (c.max) list = list.filter(p => p.price !== null && p.price <= c.max);
  if (c.min) list = list.filter(p => p.price !== null && p.price >= c.min);
  const rank = cfg.ranking || 'price_asc';
  list.sort((a, b) => rank === 'price_desc' ? (b.price || 0) - (a.price || 0)
    : (rank === 'closest_to_budget' && c.max) ? (c.max - a.price) - (c.max - b.price)
    : (a.price || 0) - (b.price || 0));
