// ---------- booking collection ----------
function handleBooking() {
  const prev = st.stage;
  const selected = byId(st.selectedPropertyId);
  if (!isAvail(selected)) {
    st = fresh();
    say('Sorry, that property is no longer available. 😔 Tell me your preferred location and budget and I\'ll find other options.');
    return;
  }
  if (flags.cmd === 'change_details' && (prev === 'ask_date' || prev === 'ask_time')) {
    st.name = ''; st.email = ''; st.stage = 'ask_name';
    say('Sure! What name should I use for the appointment?');
    return;
  }
  let ackName = '';
  if (P.email) st.email = P.email;
  if (prev === 'ask_name' && P.nameCandidate) { st.name = P.nameCandidate; ackName = st.name.split(' ')[0]; }
  const allowDT = prev !== 'ask_name' || !!P.email;
  if (allowDT) { if (P.date) st.date = P.date; if (P.time) st.time = P.time; }

  let problem = '';
  if (st.date) { const e = checkDate(st.date); if (e) { problem = e; st.date = ''; } }
  if (st.time) { const e = checkTime(st.date || null, st.time); if (e) { problem = e; st.time = ''; } }

  const missing = !st.name ? 'ask_name' : !st.email ? 'ask_email' : !st.date ? 'ask_date' : !st.time ? 'ask_time' : null;
  if (missing) {
    st.stage = missing;
    let lead = problem ? `⚠️ ${problem}\n\n` : '';
    if (!problem && prev === 'ask_name' && !P.nameCandidate) lead = 'Sorry, I didn\'t catch a valid name. ';
    if (!problem && prev === 'ask_email' && !P.email) lead = 'That doesn\'t look like a valid email address. ';
    if (missing === 'ask_name') say(`${lead}What name should I use for the appointment?`);
    else if (missing === 'ask_email') say(`${lead}${ackName ? `Thanks, ${ackName}! ` : ''}What's the best email address for your appointment confirmation?`);
    else if (missing === 'ask_date') {
      const thanks = (!lead && prev === 'ask_email') ? 'Thanks! ' : '';
      if (st.time) say(`${lead}${thanks}Got it, ${prettyTime(st.time)}. Which date would you like for the visit? (e.g. *${exampleDate()}*)`);
      else say(`${lead}${thanks}What date and time would you prefer for the visit? (e.g. *${exampleDate()} at 11:00 AM*)`);
    } else say(`${lead}${(!lead && st.date) ? `Noted, ${prettyDate(st.date)}. ` : ''}What time would you prefer? Viewings run ${prettyTime(earliest)} to ${prettyTime(latest)}.`);
    return;
  }
