  out.booking = {
    propertyId: selected.id, title: selected.title || selected.type, locationText: locText(selected),
    agent: selected.agent, agentPhone: selected.agentPhone,
    name: st.name, email: st.email, date: st.date, time: st.time,
    prettyDate: prettyDate(st.date), prettyTime: prettyTime(st.time)
