}

// ---------- idle / search flow ----------
function startBooking(sel) {
  const c = ctx.customer;
  st.selectedPropertyId = sel.id; st.date = ''; st.time = ''; st.name = ''; st.email = '';
  if (c.name && c.email) {
    st.name = c.name; st.email = c.email; st.stage = 'ask_date';
    say(`Excellent choice! I'll arrange a viewing for *${sel.title || sel.type}* (${sel.id}) under *${c.name}* (${c.email}).\n\nWhat date and time would you prefer? (e.g. *${exampleDate()} at 11:00 AM*)\n\n_Type *CHANGE DETAILS* to use a different name or email, or *MENU* to start over._`);
  } else {
    st.stage = 'ask_name';
    say(`Absolutely! I can help arrange a viewing for *${sel.title || sel.type}* (${sel.id}). What name should I use for the appointment?\n\n_You can type *MENU* at any time to start over._`);
  }
}
function showDetails(p) {
  const lines = [`*${p.title || p.type}*`, `📍 ${locText(p)}`, `💰 ${fmtPrice(p.price, p.currency)}`];
  if (p.size) lines.push(`📐 ${p.size}`);
  if (p.type) lines.push(`🏷️ ${p.type}`);
  if (p.description) lines.push(`\n${p.description}`);
  if (p.features) lines.push(`✨ ${p.features}`);
  lines.push(`\n🆔 ID: ${p.id}\nStatus: ${isAvail(p) ? '✅ Available' : '❌ Not available'}`);
