    say('Happy to arrange a viewing! Which property would you like to visit? Please reply with the *number* (e.g. 1) or the *property ID* (e.g. P001) from my list.\n\nIf you haven\'t seen a list yet, tell me the location and budget and I\'ll find options.');
    return;
  }

  crit = buildCriteria();
