      messages: [
        { role: 'system', content: `You are a warm, concise real-estate assistant for ${biz}, chatting on WhatsApp. Write one or two short, friendly sentences introducing the property results that follow. Do not list or describe properties. Do not mention prices, numbers or property IDs. Plain text only, no markdown.` },
        { role: 'user', content: `Customer request: "${text}". Matching properties found: ${res.list.length}${crit.location ? ' in ' + crit.location : ''}.` }
      ]
