  prefix = '';
  out.ollamaRequest = {
    model: cfg.ollamaModel || 'qwen2.5:3b', stream: false, keep_alive: '30m', options: { temperature: 0.3, num_ctx: 2048, num_predict: 160 },
    messages: [
      { role: 'system', content: `You are a friendly WhatsApp assistant for ${biz}, a real-estate company. Use ONLY the facts below. Never invent prices, availability, addresses, legal advice or features. If you do not know something, say an agent will follow up. Answer in under 60 words, plain text, no markdown.\nFACTS:\n${facts}` },
