// ---------- main routing ----------
if (ctx.unsupported) {
  say('Sorry, I can only read text messages at the moment. Please type your request, for example the location and budget you have in mind.');
} else if (flags.cmd === 'reset' || (flags.isGreeting && !isBooking(st.stage))) {
  st = fresh(); say(greeting());
} else if (flags.cmd === 'cancel') {
  if (isBooking(st.stage)) { st = fresh(); say('No problem, I\'ve cancelled that booking request. Tell me what you\'re looking for whenever you\'re ready, or type *MENU* to start over.'); }
  else { st = fresh(); say(greeting()); }
} else if (isBooking(st.stage)) {
