} else {
  handleIdle();
}

// ---------- rows for Google Sheets ----------
const stageLabel = s => isBooking(s) ? 'Booking' : (s === 'completed' ? 'Completed' : 'Search');
const stateRowOf = s => ({
  CustomerPhone: phone, Stage: s.stage, SelectedPropertyID: s.selectedPropertyId || '', CollectedName: s.name || '', CollectedEmail: s.email || '',
  PreferredDate: s.date || '', PreferredTime: s.time || '', UpdatedAt: nowIso,
  LastResultIDs: (s.lastResultIds || []).join(','), LastCriteria: s.lastCriteria ? JSON.stringify(s.lastCriteria) : '', LastMessageID: ctx.messageId
});
const c0 = ctx.customer;
const customerRowOf = s => ({
  CustomerPhone: phone,
  CustomerName: s.name || c0.name || ctx.profileName || '',
  Email: s.email || c0.email || '',
  Budget: (crit && crit.max) ? crit.max : c0.budget,
