  stateRowRetry = stateRowOf(Object.assign({}, st, { stage: 'ask_time', time: '', lastResultIds: [] }));
} else { stateRow = stateRowOf(st); customerRow = customerRowOf(st); }

return [{ json: { action: out.action, phone, messages: out.messages, compose: out.compose, booking: out.booking, ollamaRequest: out.ollamaRequest, stateRow, stateRowRetry, customerRow } }];

// Compose Final: merge the (optional) Ollama wording with verified data.
const r = $('Resolve Action').first().json;
const j = $input.first().json || {};
const c = r.compose;
let raw = (j.message && j.message.content) ? String(j.message.content).trim() : '';
raw = raw.replace(/^["'“”]+|["'“”]+$/g, '').replace(/\*\*/g, '*').trim();
const numbersOk = s => (s.match(/\d+/g) || []).every(n => String(c.allowedText).includes(n));
const limit = c.kind === 'results' ? 300 : 700;
const valid = (raw && raw.length <= limit && !/[$€£₦]/.test(raw) && numbersOk(raw)) ? raw : '';

const messages = [];
if (c.kind === 'results') {
  messages.push({ type: 'text', body: ((c.prefix || '') + (valid || c.fallbackIntro) + '\n\n' + c.listing + '\n\n' + c.cta).slice(0, 4000) });
  (c.images || []).forEach(m => messages.push(m));
} else {
  messages.push({ type: 'text', body: ((c.prefix || '') + (valid || c.fallback) + '\n\n' + c.nudge).slice(0, 4000) });
}
return [{ json: { phone: r.phone, messages, stateRow: r.stateRow, customerRow: r.customerRow } }];

// Prepare Appointment: duplicate + slot-conflict checks, ID generation, e-mail content.
const r = $('Resolve Action').first().json;
const cfg = $('Config').first().json;
const b = r.booking;
const norm = v => String(v === undefined || v === null ? '' : v).trim();
const digits = v => norm(v).replace(/\D/g, '');
const pad = n => String(n).padStart(2, '0');
const normDate = v => { const s = norm(v); if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10); if (/^\d{5}(\.\d+)?$/.test(s)) return new Date(Date.UTC(1899, 11, 30) + Math.floor(Number(s)) * 86400000).toISOString().slice(0, 10); return s; };
const normTime = v => { const s = norm(v); if (/^\d{1,2}:\d{2}/.test(s)) { const p = s.split(':'); return pad(+p[0]) + ':' + p[1].slice(0, 2); } if (s !== '' && !isNaN(Number(s)) && Number(s) >= 0 && Number(s) < 1) { const m = Math.round(Number(s) * 1440); return pad(Math.floor(m / 60)) + ':' + pad(m % 60); } return s; };
const esc = s => String(s).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));

const existing = $('Read Appointments').all().map(i => i.json || {}).filter(x => norm(x.AppointmentID));
const active = existing.filter(x => !/cancel/i.test(norm(x.Status)));
const sameSlot = x => normDate(x.PreferredDate) === b.date && normTime(x.PreferredTime) === b.time;
const sameProp = x => norm(x.PropertyID).toLowerCase() === b.propertyId.toLowerCase();
const dup = active.find(x => sameSlot(x) && sameProp(x) && digits(x.CustomerPhone) === digits(r.phone));
const clash = active.find(x => sameSlot(x) && (sameProp(x) || (b.agent && norm(x.AssignedAgent).toLowerCase() === b.agent.toLowerCase())));

if (dup) {
  return [{ json: { ok: false, phone: r.phone, stateRow: r.stateRow, customerRow: r.customerRow, messages: [{ type: 'text', body: `ℹ️ You already have a viewing request for *${b.title}* on ${b.prettyDate} at ${b.prettyTime} (Reference: *${norm(dup.AppointmentID)}*). Our agent will contact you shortly to confirm.\n\nTell me a location and budget if you'd like to keep browsing.` }] } }];
}
if (clash) {
  return [{ json: { ok: false, phone: r.phone, stateRow: r.stateRowRetry, customerRow: Object.assign({}, r.customerRow, { ConversationStage: 'Booking' }), messages: [{ type: 'text', body: `😕 Sorry, that time slot has just been taken. Please choose another time on ${b.prettyDate}, or send a different date and time.` }] } }];
}

const ids = new Set(existing.map(x => norm(x.AppointmentID)));
const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
let id; do { id = `APT-${stamp}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`; } while (ids.has(id));

const appointment = {
  AppointmentID: id, CreatedAt: new Date().toISOString(), CustomerName: b.name, CustomerPhone: r.phone, CustomerEmail: b.email,
  PropertyID: b.propertyId, PropertyTitle: b.title, PropertyLocation: b.locationText,
  PreferredDate: b.date, PreferredTime: b.time, Status: 'Pending', AssignedAgent: b.agent || '',
  CustomerEmailStatus: 'Pending', AdminEmailStatus: 'Pending'
};
const biz = esc(cfg.businessName || 'Our team');
const row = (k, v) => `<tr><td style="padding:6px 12px;color:#555">${k}</td><td style="padding:6px 12px"><b>${v}</b></td></tr>`;
const customerHtml = `<div style="font-family:Arial,sans-serif;font-size:15px;color:#222">
<p>Hello ${esc(b.name)},</p>
<p>Thank you for your interest. We have recorded your property viewing request:</p>
<table style="border-collapse:collapse;background:#f6f8fa;border-radius:6px">
${row('Reference', esc(id))}${row('Property', esc(b.title) + ' (' + esc(b.propertyId) + ')')}${row('Location', esc(b.locationText))}${row('Requested date', esc(b.prettyDate))}${row('Requested time', esc(b.prettyTime))}
</table>
<p>Our agent${b.agent ? ' <b>' + esc(b.agent) + '</b>' : ''}${b.agentPhone ? ' (' + esc(b.agentPhone) + ')' : ''} will contact you shortly to confirm the visit.</p>
<p>Kind regards,<br>${biz}</p></div>`;
const adminHtml = `<div style="font-family:Arial,sans-serif;font-size:15px;color:#222">
<p><b>New property viewing request</b></p>
<table style="border-collapse:collapse;background:#f6f8fa;border-radius:6px">
${row('Appointment ID', esc(id))}${row('Customer', esc(b.name))}${row('WhatsApp', esc(r.phone))}${row('Email', esc(b.email))}${row('Property', esc(b.title) + ' (' + esc(b.propertyId) + ')')}${row('Location', esc(b.locationText))}${row('Requested date', esc(b.prettyDate))}${row('Requested time', esc(b.prettyTime))}${row('Assigned agent', esc(b.agent || 'Unassigned'))}${row('Status', 'Pending')}
</table></div>`;

return [{ json: { ok: true, appointment, emails: {
  customer: { to: b.email, subject: 'Your Real Estate Viewing Request', html: customerHtml },
  admin: { to: cfg.adminEmail, subject: 'New Property Viewing Appointment', html: adminHtml }
} } }];

// Notification Status Row: record whether each e-mail was sent (separate from the booking itself).
const a = $('Prepare Appointment').first().json.appointment;
const c = $('Send Customer Email').first().json || {};
const d = $('Send Admin Email').first().json || {};
const st = j => (j && (j.id || j.threadId) && !j.error) ? 'Sent' : ('Failed: ' + String((j && j.error && (j.error.message || j.error)) || 'no response').slice(0, 120));
return [{ json: Object.assign({}, a, { CustomerEmailStatus: st(c), AdminEmailStatus: st(d) }) }];

// Booking Result: final WhatsApp confirmation (sent only after the appointment row was saved).
const r = $('Resolve Action').first().json;
const a = $('Prepare Appointment').first().json.appointment;
const n = $('Notification Status Row').first().json;
const b = r.booking;
let t = `✅ Thank you, ${b.name.split(' ')[0]}! Your viewing request has been recorded.

` +
  `🏡 *${b.title}* (${b.propertyId})
📍 ${b.locationText}
📅 ${b.prettyDate} at ${b.prettyTime}
🔖 Reference: *${a.AppointmentID}*

` +
  `Our agent${b.agent ? ' ' + b.agent : ''}${b.agentPhone ? ' (' + b.agentPhone + ')' : ''} will contact you shortly to confirm the visit.`;
t += /^Sent/.test(n.CustomerEmailStatus) ? `
📧 A confirmation email is on its way to ${b.email}.` : '
(We could not send the confirmation email just now, but your request is saved.)';
t += '

Tell me a location and budget any time if you'd like to keep browsing.';
return [{ json: { phone: r.phone, messages: [{ type: 'text', body: t }], stateRow: r.stateRow, customerRow: r.customerRow } }];

// Booking Error Result: the appointment row could not be saved -> tell the customer honestly, allow retry.
const r = $('Resolve Action').first().json;
return [{ json: { phone: r.phone,
  messages: [{ type: 'text', body: '⚠️ Sorry, I hit a technical problem while saving your booking, so it was *not* recorded. Please send your preferred time again in a moment and I\'ll retry.' }],
  stateRow: r.stateRowRetry, customerRow: Object.assign({}, r.customerRow, { ConversationStage: 'Booking' }) } }];

// Build Outbound: one WhatsApp Cloud API payload per message.
const e = $input.first().json;
const base = { messaging_product: 'whatsapp', recipient_type: 'individual', to: e.phone };
return e.messages.map(m => ({ json: {
  payload: m.type === 'image'
    ? Object.assign({}, base, { type: 'image', image: { link: m.link, caption: String(m.caption || '').slice(0, 1000) } })
    : Object.assign({}, base, { type: 'text', text: { preview_url: false, body: String(m.body).slice(0, 4000) } }),
  stateRow: e.stateRow, customerRow: e.customerRow
} }));
